{
  "skill": "harness-engineering",
  "description": "Test cases for the Harness Engineering skill — evaluable inline in Claude.ai",
  "eval_instructions": "For each test case, read the SKILL.md and relevant reference files, then complete the task as the skill instructs. Evaluate against the assertions.",
  "cases": [
    {
      "id": "TC01",
      "name": "Multi-session setup for new project",
      "prompt": "I want to build a task management web app (like Trello) using Node.js and React. I'm going to use Claude Code across multiple sessions. How should I set up the harness so Claude doesn't lose progress between sessions?",
      "expected_behaviors": [
        "Recommends dual-agent architecture (Initializer + Coding Agent)",
        "Explains claude-progress.txt purpose and structure",
        "Explains features.json with acceptance criteria",
        "Mentions startup ritual (pwd, read progress, check features, run tests)",
        "Mentions keeping code in clean state at session end",
        "Provides concrete file templates or examples"
      ],
      "assertions": [
        {
          "type": "contains_concept",
          "concept": "Initializer agent or initialization step",
          "required": true
        },
        {
          "type": "contains_concept",
          "concept": "claude-progress.txt or progress file",
          "required": true
        },
        {
          "type": "contains_concept",
          "concept": "features.json or feature list",
          "required": true
        },
        {
          "type": "contains_concept",
          "concept": "startup ritual or startup sequence",
          "required": true
        },
        {
          "type": "includes_template_or_example",
          "required": true
        }
      ],
      "grading": "PASS if at least 4/5 assertions met. FAIL if claude-progress.txt or features.json are both missing."
    },
    {
      "id": "TC02",
      "name": "Codebase legibility for agents",
      "prompt": "I have a 50k line TypeScript monorepo with 6 engineers. We want to start using Codex heavily but the agents keep getting lost and producing inconsistent code. How should I restructure the repo docs for agent legibility?",
      "expected_behaviors": [
        "Recommends progressive disclosure docs structure",
        "Explains _map.md as navigation entry point",
        "Recommends domain README files",
        "Warns against monolithic AGENTS.md",
        "Mentions knowledge visibility principle (if not in repo, doesn't exist for agents)",
        "Provides concrete directory structure"
      ],
      "assertions": [
        {
          "type": "contains_concept",
          "concept": "_map.md or navigation file as entry point",
          "required": true
        },
        {
          "type": "contains_concept",
          "concept": "domain README or per-domain documentation",
          "required": true
        },
        {
          "type": "contains_concept",
          "concept": "progressive disclosure or layered docs",
          "required": false
        },
        {
          "type": "warns_against",
          "concept": "monolithic AGENTS.md or single large instruction file",
          "required": true
        },
        {
          "type": "includes_directory_structure",
          "required": true
        }
      ],
      "grading": "PASS if _map.md concept AND domain README concept both present. FAIL otherwise."
    },
    {
      "id": "TC03",
      "name": "Architectural constraints setup",
      "prompt": "Our Codex agents keep introducing circular dependencies and importing from the wrong layers. We have a clean-ish architecture now but agents are slowly breaking it. What should we do?",
      "expected_behaviors": [
        "Recommends dependency layer model",
        "Recommends CI-enforced linting (dependency-cruiser or import-linter)",
        "Explains the difference between enforced invariants vs style guides",
        "Provides concrete tool setup commands or config",
        "Mentions structural tests as complementary approach"
      ],
      "assertions": [
        {
          "type": "recommends_tool",
          "concept": "dependency-cruiser or import-linter or equivalent",
          "required": true
        },
        {
          "type": "contains_concept",
          "concept": "CI-enforced or automated enforcement",
          "required": true
        },
        {
          "type": "contains_concept",
          "concept": "dependency layers or layer model",
          "required": true
        },
        {
          "type": "provides_config_or_commands",
          "required": true
        }
      ],
      "grading": "PASS if enforcement tool recommended AND CI enforcement mentioned. FAIL otherwise."
    },
    {
      "id": "TC04",
      "name": "AI slop and entropy management",
      "prompt": "After 3 months of heavy Codex usage, our codebase has 1200 files and it's getting messy — lots of dead code, inconsistent patterns, and outdated comments. We're spending 30% of our engineering time manually cleaning. How do we fix this?",
      "expected_behaviors": [
        "Recommends Golden Principles file",
        "Recommends automated GC agent pattern",
        "Explains how GC agent should work (read principles, scan, open PRs)",
        "Notes GC should be proportional to throughput (not manual)",
        "Provides quality tracking recommendation",
        "Warns against manual cleanup sprints as solution"
      ],
      "assertions": [
        {
          "type": "contains_concept",
          "concept": "golden principles or quality standards document",
          "required": true
        },
        {
          "type": "contains_concept",
          "concept": "GC agent or garbage collection agent",
          "required": true
        },
        {
          "type": "contains_concept",
          "concept": "automated or scheduled cleanup",
          "required": true
        },
        {
          "type": "mentions_automation_over_manual",
          "required": true
        }
      ],
      "grading": "PASS if golden-principles AND automated GC agent both mentioned. FAIL otherwise."
    },
    {
      "id": "TC05",
      "name": "Diagnosing agent failure (don't hand-code)",
      "prompt": "Our coding agent keeps failing to implement the payment integration correctly — it gets confused about which service to call and produces broken code. My team's instinct is to just write the payment code manually. Should we?",
      "expected_behaviors": [
        "Strongly advises against hand-coding as solution",
        "Explains the 'Agent struggles = missing capability' mental model",
        "Provides diagnostic framework (tools? docs? constraints? context?)",
        "Recommends having agent build the missing capability",
        "Explains compounding returns of fixing root cause"
      ],
      "assertions": [
        {
          "type": "advises_against",
          "concept": "hand-coding or writing code manually as the solution",
          "required": true
        },
        {
          "type": "contains_concept",
          "concept": "diagnose missing capability",
          "required": true
        },
        {
          "type": "provides_diagnostic_steps",
          "required": true
        },
        {
          "type": "mentions_compounding_returns",
          "required": false
        }
      ],
      "grading": "PASS if advises against hand-coding AND provides diagnosis approach. FAIL if response suggests writing code manually is acceptable."
    },
    {
      "id": "TC06",
      "name": "Greenfield setup walkthrough",
      "prompt": "I'm starting a new SaaS product from scratch and want to build it entirely with Claude Code as the primary developer. Give me the complete setup checklist.",
      "expected_behaviors": [
        "Provides ordered setup steps",
        "Covers docs structure initialization",
        "Covers dependency layer definition",
        "Covers testing framework setup",
        "Covers features.json + claude-progress.txt creation",
        "Mentions starting at Autonomy Level 1",
        "Includes actual commands or templates"
      ],
      "assertions": [
        {
          "type": "provides_ordered_checklist",
          "required": true
        },
        {
          "type": "mentions_at_least_n_components",
          "n": 4,
          "components": ["docs structure", "dependency layers", "testing", "features.json", "progress file", "autonomy level"],
          "required": true
        },
        {
          "type": "includes_commands_or_code",
          "required": true
        }
      ],
      "grading": "PASS if ordered steps provided AND at least 4 key components covered. FAIL if fewer than 3 components addressed."
    },
    {
      "id": "TC07",
      "name": "Retrofit existing codebase",
      "prompt": "We have a 2-year-old Django monolith with 200k lines of code and 8 developers. We want to start using AI agents for development but can't rewrite everything. What's the incremental path?",
      "expected_behaviors": [
        "Acknowledges can't do everything at once",
        "Provides phased/incremental approach",
        "Recommends starting with documentation (existing state)",
        "Recommends going-forward enforcement (not retroactive)",
        "Suggests starting agents in non-critical domains first",
        "Provides timeline guidance (weeks/months)"
      ],
      "assertions": [
        {
          "type": "provides_phased_approach",
          "required": true
        },
        {
          "type": "contains_concept",
          "concept": "going-forward enforcement or new files only",
          "required": true
        },
        {
          "type": "recommends_starting_small",
          "concept": "non-critical domain or single team/module",
          "required": true
        },
        {
          "type": "provides_timeline",
          "required": true
        }
      ],
      "grading": "PASS if phased approach AND going-forward enforcement concept both present. FAIL if response suggests big-bang migration."
    },
    {
      "id": "TC08",
      "name": "PR review bottleneck",
      "prompt": "We're running Codex at full speed and generating 40-50 PRs per day. Our 3 human engineers can't keep up with reviews. Everything is blocked. How do we scale review to match generation throughput?",
      "expected_behaviors": [
        "Recommends risk-based review triage",
        "Provides PR category taxonomy",
        "Recommends auto-merge for low-risk categories",
        "Mentions agent self-review as intermediate step",
        "Mentions CI gates as substitute for human review",
        "Does NOT recommend hiring more reviewers as primary solution"
      ],
      "assertions": [
        {
          "type": "contains_concept",
          "concept": "risk-based triage or risk categorization",
          "required": true
        },
        {
          "type": "contains_concept",
          "concept": "auto-merge or automated approval for low-risk",
          "required": true
        },
        {
          "type": "distinguishes_pr_categories",
          "required": true
        },
        {
          "type": "mentions_agent_self_review",
          "required": false
        }
      ],
      "grading": "PASS if risk-based triage AND auto-merge for low-risk both mentioned. FAIL if only solution offered is human review."
    }
  ],
  "inline_eval_procedure": {
    "description": "How to run these evals inline in Claude.ai without subprocesses",
    "steps": [
      "1. Open the skill SKILL.md and relevant references",
      "2. For each test case, read the prompt and imagine you are Claude with access to the skill",
      "3. Generate a response following the skill's instructions",
      "4. Check the response against each assertion in the test case",
      "5. Record PASS/FAIL/PARTIAL per assertion",
      "6. Overall grade: PASS if grading criteria met, FAIL otherwise",
      "7. Note any gaps in skill content revealed by failures"
    ],
    "scoring": {
      "pass_threshold": "6 out of 8 test cases must PASS",
      "critical_cases": ["TC01", "TC05"],
      "note": "TC01 (multi-session setup) and TC05 (don't hand-code) are critical — must both PASS"
    }
  },
  "iteration_notes": {
    "version": "1.0",
    "known_gaps": [],
    "suggested_improvements": []
  }
}
